            lpszCommandLine++;

        StartupInfo.dwFlags = 0;
        GetStartupInfoA(&StartupInfo);

        mainret = WinMain(GetModuleHandleA(0), 0, (char*)lpszCommandLine,
                          StartupInfo.dwFlags & 1 ? StartupInfo.wShowWindow : 10);

        if (!managedapp)
            exit(mainret);

        _cexit();
    }
