    int v;
    unsigned char pad[0x7c - sizeof(int)];
    E() : v(0) { ++g_live; }
    E(int x) : v(x) { ++g_live; }
    E(const E& o) : v(o.v) { ++g_live; }
    E& operator=(const E& o) { v = o.v; return *this; }
    ~E() { --g_live; }
