        a._M_clear(); b._M_clear();
    }
    {   // self-assignment is a no-op
        V a; a.reserve_with(3, 3);
        a = a;
        int want[] = { 1, 2, 3 };
        ok = ok && same(a, want, 3);
        a._M_clear();
    }
